  pg_xo    <= XO17 & XO16 & XO15 & XO14 & XO13 & XO12 & XO11 & XO10 & XO9 & XO8 & XO7 & XO6 & XO5 & XO4 & XO3 & XO2 & XO1 & XO0;
  u_phase_generator: entity work.amy1_phase_generator port map (
    clk => clk,
    tick => tick,
    sample => sample,
    clkn_ph => CLKN_PH,
    ld_voice => pg_ld_voice,
    voice => pg_voice,
    cnt => pg_cnt,
    clrph => CLRPH,
    xo => pg_xo,
    clrdisp => CLRDISP,
    arg => pg_arg,
    ram_addr => pg_ram_addr,
    ram_we => pg_ram_we,
    ram_wdata => pg_ram_wdata,
    ram_q => phaseram_q
  );
  ARG0 <= pg_arg(0);
  ARG1 <= pg_arg(1);
  ARG2 <= pg_arg(2);
  ARG3 <= pg_arg(3);
  ARG4 <= pg_arg(4);
  ARG5 <= pg_arg(5);
  ARG6 <= pg_arg(6);
  ARG7 <= pg_arg(7);
  SARG8 <= pg_arg(8);
  SARG9 <= pg_arg(9);
  SARG10 <= pg_arg(10);
  SARG11 <= pg_arg(11);
  SARG12 <= pg_arg(12);
  SARG13 <= pg_arg(13);
  phaseram_addr <= pg_ram_addr;
  phaseram_we <= pg_ram_we;
  phaseram_wdata <= pg_ram_wdata;

  -- sine_rom (hand-written)
  sr_arg <= SARG13 & SARG12 & SARG11 & SARG10 & SARG9 & SARG8 & ARG7 & ARG6 & ARG5 & ARG4 & ARG3 & ARG2 & ARG1 & ARG0;
  u_sine_rom: entity work.amy1_sine_rom port map (
    clk => clk,
    tick => tick,
    sample => sample,
    arg => sr_arg,
    hs => sr_hs,
    base_addr => sr_base_addr,
    base_q => srombs_q,
    int_addr => sr_int_addr,
    int_q => sromint_q
  );
  HS0 <= sr_hs(0);
  HS1 <= sr_hs(1);
  HS2 <= sr_hs(2);
  HS3 <= sr_hs(3);
  HS4 <= sr_hs(4);
  HS5 <= sr_hs(5);
  HS6 <= sr_hs(6);
  HS7 <= sr_hs(7);
  HS8 <= sr_hs(8);
  HS9 <= sr_hs(9);
  HS10 <= sr_hs(10);
  HS11 <= sr_hs(11);
  HS12 <= sr_hs(12);
  srombs_addr <= sr_base_addr;
  sromint_addr <= sr_int_addr;

  -- exp_rom (hand-written)
  xr_log <= LOG12 & LOG11 & LOG10 & LOG9 & LOG8 & LOG7 & LOG6 & LOG5 & LOG4 & LOG3 & LOG2 & LOG1 & LOG0;
  u_exp_rom: entity work.amy1_exp_rom port map (
    clk => clk,
    tick => tick,
    log => xr_log,
    fan => FAN,
    xo => xr_xo,
    clrdisp => xr_clrdisp,
    base_addr => xr_base_addr,
    base_q => xrombs_q,
    int_addr => xr_int_addr,
    int_q => xromint_q
  );
  XO0 <= xr_xo(0);
  XO1 <= xr_xo(1);
  XO2 <= xr_xo(2);
  XO3 <= xr_xo(3);
  XO4 <= xr_xo(4);
  XO5 <= xr_xo(5);
  XO6 <= xr_xo(6);
  XO7 <= xr_xo(7);
  XO8 <= xr_xo(8);
  XO9 <= xr_xo(9);
  XO10 <= xr_xo(10);
  XO11 <= xr_xo(11);
  XO12 <= xr_xo(12);
  XO13 <= xr_xo(13);
  XO14 <= xr_xo(14);
  XO15 <= xr_xo(15);
  XO16 <= xr_xo(16);
  XO17 <= xr_xo(17);
  CLRDISP <= xr_clrdisp;
  X232107_X5K0 <= not xr_xo(0);
  X242108_X5K0 <= not xr_xo(1);
  X252109_X5K0 <= not xr_xo(2);
  X262110_X5K0 <= not xr_xo(3);
  X272111_X5K0 <= not xr_xo(4);
  X282112_X5K0 <= not xr_xo(5);
  X292113_X5K0 <= not xr_xo(6);
  X302115_X5K0 <= not xr_xo(7);
  xrombs_addr <= xr_base_addr;
  xromint_addr <= xr_int_addr;
  octspl_addr <= (others => '0');

  -- output_accumulator (hand-written)
  oa_hs      <= HS12 & HS11 & HS10 & HS9 & HS8 & HS7 & HS6 & HS5 & HS4 & HS3 & HS2 & HS1 & HS0;
  oa_load    <= not ILDSAMPN;
  oa_outstb  <= not OUTSTBN;
  oa_samp_oe <= not OEN;
  u_output_accumulator: entity work.amy1_output_accumulator port map (
    clk => clk,
    tick => tick,
    sample => sample,
    clkn_ph => CLKN_PH,
    hs => oa_hs,
    load => oa_load,
    test => TST,
    outstb => oa_outstb,
    samp_oe => oa_samp_oe,
    ld_samp => oa_ld_samp,
    samp_latch => oa_latch,
    samp_pin => oa_pin
  );
  LDSAMP <= oa_ld_samp;
  SAMP0L <= oa_latch(0);
  SAMP1L <= oa_latch(1);
  SAMP2L <= oa_latch(2);
  SAMP3L <= oa_latch(3);
  SAMP4L <= oa_latch(4);
  SAMP5L <= oa_latch(5);
  SAMP6L <= oa_latch(6);
  SAMP7L <= oa_latch(7);
  SAMP8L <= oa_latch(8);
  SAMP9L <= oa_latch(9);
  SAMP10L <= oa_latch(10);
  SAMP11L <= oa_latch(11);
  SAMP12L <= oa_latch(12);
  SAMP13L <= oa_latch(13);
  SAMP14L <= oa_latch(14);
  SAMP15L <= oa_latch(15);
  SAMP16L <= oa_latch(16);
  SAMP0 <= oa_pin(0);
  SAMP1 <= oa_pin(1);
  SAMP2 <= oa_pin(2);
  SAMP3 <= oa_pin(3);
  SAMP4 <= oa_pin(4);
  SAMP5 <= oa_pin(5);
  SAMP6 <= oa_pin(6);
  SAMP7 <= oa_pin(7);
  SAMP8 <= oa_pin(8);
  SAMP9 <= oa_pin(9);
  SAMP10 <= oa_pin(10);
  SAMP11 <= oa_pin(11);
  SAMP12 <= oa_pin(12);
  SAMP13 <= oa_pin(13);
  SAMP14 <= oa_pin(14);
  SAMP15 <= oa_pin(15);

  -- noise_generator (hand-written)
  nz_p         <= P0 & P1 & P2 & P3;
  nz_hadr      <= not (HADR5N & HADR4N & HADR3N & HADR2N & HADR1N & HADR0N);
  nz_host_we   <= not WRNZN;
  nz_host_data <= NRIN2 & NRIN1 & NRIN0;
  nz_mute      <= ZEROB or TST;
  u_noise_generator: entity work.amy1_noise_generator port map (
    clk => clk,
    tick => tick,
    clk_ph => CLK_PH,
    p => nz_p,
    sync => SYNC,
    odd => ODDEV,
    hadr => nz_hadr,
    host_mode => NZINIT,
    host_we => nz_host_we,
    host_data => nz_host_data,
    sync_d => nz_sync_d,
    gen_sel => CVNL1,
    mute => nz_mute,
    noise => nz_noise,
    serial => nz_serial,
    ram_addr => nz_ram_addr,
    ram_we => nz_ram_we,
    ram_wdata => nz_ram_wdata,
    ram_q => noise_q
  );
  B0 <= nz_noise(0);
  B1 <= nz_noise(1);
  B2 <= nz_noise(2);
  B3 <= nz_noise(3);
  B4 <= nz_noise(4);
  B5 <= nz_noise(5);
  B6 <= nz_noise(6);
  B7 <= nz_noise(7);
  B8 <= nz_noise(8);
  B9 <= nz_noise(9);
  B10 <= nz_noise(10);
  BSIGN <= nz_noise(11);
  BOUT <= nz_serial;
  SYNCD <= nz_sync_d;
  NZINITB <= not NZINITN;
  noise_addr <= nz_ram_addr;
  noise_we <= nz_ram_we;
  noise_wdata <= nz_ram_wdata;
  NOMXA0 <= '0';
  NOMXA1 <= '0';
  NOMXA2 <= '0';

  process (clk)
  begin
    if rising_edge(clk) then
      if step_en = '1' then
        step_reg <= step_next;
      end if;
    end if;
  end process;
end architecture;
